// Canvas dimensions for the map area
#define EQ_MAP_W        790
#define EQ_MAP_H        540

// Convert geographic coords to map canvas pixel coords
// Use these macros when plotting earthquake dots
#define EQ_LON_TO_X(lon)  ((int)(((lon) - EQ_MAP_LON_MIN) / (EQ_MAP_LON_MAX - EQ_MAP_LON_MIN) * EQ_MAP_W))
#define EQ_LAT_TO_Y(lat)  ((int)((EQ_MAP_LAT_MAX - (lat)) / (EQ_MAP_LAT_MAX - EQ_MAP_LAT_MIN) * EQ_MAP_H))

